import { ReaderWindowCoordinator } from '../../app/ReaderWindowCoordinator';
import { MANGA_DIRECTORY_VISUAL, mangaDirectoryColor, mangaDirectoryScale } from './MangaDirectoryVisual';
import { MangaDirectoryPressFeedback } from './MangaDirectoryPressFeedback';
import type { LocalReadingTocEntry } from '../reading/LocalReadingFlowGateway';
import type { MangaDirectoryRowPresentation } from './MangaDirectoryPresentation';
import { mangaDirectoryDisplay } from './MangaDirectoryDisplay';
import type { MangaDirectoryLayoutRow, MangaDirectoryLabel } from './MangaDirectoryLayout';
import { READER_FONT_NOTO_SANS_SC_UI_REGULAR, READER_FONT_NOTO_SANS_SC_UI_550, READER_FONT_NOTO_SANS_SC_UI_600 } from '../common/ReaderFontFamilies';
@Component
export struct MangaDirectoryEntryRow extends   {
    constructor(?: {
        row?: MangaDirectoryLayoutRow;
        presentation?: Map<number, MangaDirectoryRowPresentation>;
        scheme?: string;
        private windowMetricsRevision?: number;
        currentChapterIndex?: number;
        collapsedBranches?: number[];
        query?: string;
        showContext?: boolean;
        interactionEnabled?: boolean;
        chapterDownloadEnabled?: boolean;
        branchControlsEnabled?: boolean;
        onSelectEntry?: (entry: LocalReadingTocEntry) => void;
        onToggleBranch?: (entry: LocalReadingTocEntry) => void;
        onDownloadEntry?: (entry: LocalReadingTocEntry) => void;
    }, ?: ) { }
    @Prop
    row: MangaDirectoryLayoutRow = { kind: 'row', columns: 1, startIndex: 0, entries: [], labels: [] };
    @Prop
    presentation: Map<number, MangaDirectoryRowPresentation> = new Map<number, MangaDirectoryRowPresentation>();
    @Prop
    scheme: string = 'day';
    @StorageLink('readerWindowMetricsRevision')
    private windowMetricsRevision: number = 0;
    @Prop
    currentChapterIndex: number = -1;
    @Prop
    collapsedBranches: number[] = [];
    @Prop
    query: string = '';
    @Prop
    showContext: boolean = false;
    @Prop
    interactionEnabled: boolean = true;
    @Prop
    chapterDownloadEnabled: boolean = false;
    @Prop
    branchControlsEnabled: boolean = true;
    onSelectEntry: (entry: LocalReadingTocEntry) => void = (_entry: LocalReadingTocEntry): void => { };
    onToggleBranch: (entry: LocalReadingTocEntry) => void = (_entry: LocalReadingTocEntry): void => { };
    onDownloadEntry: (entry: LocalReadingTocEntry) => void = (_entry: LocalReadingTocEntry): void => { };
    private liveEntry(entry: LocalReadingTocEntry): LocalReadingTocEntry | undefined {
        return this.row.entries.find((current: LocalReadingTocEntry): boolean => current.index === entry.index);
    }
    private liveLabel(entry: LocalReadingTocEntry): MangaDirectoryLabel | undefined {
        const ordinal = this.row.entries.findIndex((current: LocalReadingTocEntry): boolean => current.index === entry.index);
        return ordinal >= 0 ? this.row.labels[ordinal] : undefined;
    }
    private facts(entry: LocalReadingTocEntry): MangaDirectoryRowPresentation | undefined {
        return this.liveEntry(entry) === undefined ? undefined : this.presentation.get(entry.index);
    }
    private color(role: string): string {
        return mangaDirectoryColor(role, this.scheme);
    }
    private fontScale(): number {
        const revision = this.windowMetricsRevision;
        return revision >= 0 ? mangaDirectoryScale(ReaderWindowCoordinator.metrics().systemFontScale) : 1;
    }
    private cellHeight(): number {
        return Math.max(MANGA_DIRECTORY_VISUAL.gridHeight, MANGA_DIRECTORY_VISUAL.gridPaddingY * 2 + MANGA_DIRECTORY_VISUAL.namedLineHeight * this.fontScale() +
            MANGA_DIRECTORY_VISUAL.gridBorder * 2);
    }
    private current(entry: LocalReadingTocEntry): boolean {
        const current = this.liveEntry(entry);
        return current !== undefined && current.navigable !== false && current.index === this.currentChapterIndex;
    }
    private expanded(entry: LocalReadingTocEntry): boolean {
        return this.query.trim().length > 0 || !this.collapsedBranches.includes(entry.index);
    }
    private downloadable(entry: LocalReadingTocEntry): boolean {
        const current = this.liveEntry(entry);
        return current !== undefined && this.chapterDownloadEnabled && current.navigable !== false && current.downloadState !== 'unknown';
    }
    private title(entry: LocalReadingTocEntry): string {
        const current = this.liveEntry(entry);
        if (current === undefined)
            return '';
        const title = current.title.trim();
        return title.length > 0 && title !== '第话' && title !== '第 话' ? current.title : `第${Math.max(1, current.index + 1)}话`;
    }
    private status(entry: LocalReadingTocEntry): string {
        const current = this.liveEntry(entry);
        if (current === undefined)
            return '';
        return mangaDirectoryDisplay({ title: current.title, displayTitle: current.displayTitle,
            isVip: current.isVip, isPay: current.isPay }).statusText;
    }
    private gridLabel(label: MangaDirectoryLabel): string {
        return label.kind === 'parts' ? `${label.numberText} · ${label.part}` : label.numberText ?? '';
    }
    private accessibility(entry: LocalReadingTocEntry): string {
        const facts = this.facts(entry);
        const context = facts?.contextTitle ? `${facts.contextTitle}，` : '';
        const state = facts?.group === true ? `分组，${this.expanded(entry) ? '已展开' : '已折叠'}` :
            this.liveEntry(entry)?.navigable === false ? '暂不可读' : this.liveEntry(entry)?.navigable === undefined ? '状态待确认，打开章节' : '打开章节';
        return `${context}${this.title(entry)}，${state}${this.current(entry) ? '，正在读' : ''}`;
    }
    private activateEntry(entry: LocalReadingTocEntry): void {
        const current = this.liveEntry(entry);
        if (!this.interactionEnabled || current === undefined)
            return;
        if (this.facts(current)?.group === true && this.branchControlsEnabled && this.query.trim().length === 0)
            this.onToggleBranch(current);
        else if (current.navigable !== false)
            this.onSelectEntry(current);
    }
    @Builder
    private download(entry: LocalReadingTocEntry, grid: boolean) {
        if (this.downloadable(entry)) {
            .width<
      >(grid ? MANGA_DIRECTORY_VISUAL.downloadGridWidth : 28)
                .height<
      >(grid ? this.cellHeight() - MANGA_DIRECTORY_VISUAL.gridBorder * 2 : Math.max(28, MANGA_DIRECTORY_VISUAL.namedLineHeight * this.fontScale()))
                .focusable<
      >(false).accessibilityLevel<
      >('no').onClick<
      >((): void => { });
        }
    }
    @Builder
    private numberCell(entry: LocalReadingTocEntry) {
        .layoutWeight<
    >(1).constraintSize<
    >({ minWidth: 0, minHeight: this.cellHeight() })
            .border<
    >({ width: MANGA_DIRECTORY_VISUAL.gridBorder, color: this.color('line') }).borderRadius<
    >(MANGA_DIRECTORY_VISUAL.gridRadius)
            .backgroundColor<
    >(this.color(this.current(entry) ? 'active' : 'soft'))
            .attributeModifier<
    >(new MangaDirectoryPressFeedback(this.interactionEnabled, true, this.scheme))
            .enabled<
    >(this.interactionEnabled).accessibilityText<
    >(this.accessibility(entry))
            .onClick<
    >((): void => this.activateEntry(entry));
    }
    @Builder
    private branchToggle(entry: LocalReadingTocEntry) {
        if (this.branchControlsEnabled && this.facts(entry)?.hasChildren === true) {
            .width<
      >(this.facts(entry)?.group === true ? 16 : 32).height<
      >(this.facts(entry)?.group === true ? 16 : 32)
                .margin<
      >({ left: this.facts(entry)?.group === true ? 0 : 8, right: this.facts(entry)?.group === true ? 0 : 8 })
                .responseRegion<
      >({ x: this.facts(entry)?.group === true ? -10 : 0,
                y: this.facts(entry)?.group === true ? -14 : 0,
                width: this.facts(entry)?.group === true ? 36 : 32, height: this.facts(entry)?.group === true ? 44 : 32 })
                .enabled<
      >(this.interactionEnabled && this.query.trim().length === 0)
                .attributeModifier<
      >(new MangaDirectoryPressFeedback(this.interactionEnabled && this.query.trim().length === 0, this.facts(entry)?.group !== true, this.scheme))
                .accessibilityText<
      >(`${this.title(entry)}，${this.expanded(entry) ? '收起' : '展开'}子目录`)
                .onClick<
      >((): void => {
                const current = this.liveEntry(entry);
                if (current !== undefined && this.interactionEnabled && this.branchControlsEnabled &&
                    this.query.trim().length === 0 && this.facts(current)?.hasChildren === true)
                    this.onToggleBranch(current);
            });
        }
    }
    @Builder
    private fullWidthEntry(entry: LocalReadingTocEntry) {
        if (this.branchControlsEnabled && this.facts(entry)?.readableParent === true) {
            .width<
      >('100%').border<
      >({ width: { bottom: MANGA_DIRECTORY_VISUAL.gridBorder }, color: this.color('line') });
        }
        else {
            this.fullWidthEntryBody(entry);
        }
    }
    @Builder
    private fullWidthEntryBody(entry: LocalReadingTocEntry) {
        .width<
    >('100%').layoutWeight<
    >(this.branchControlsEnabled && this.facts(entry)?.readableParent === true ? 1 : 0)
            .constraintSize<
    >({ minHeight: this.facts(entry)?.group === true ? MANGA_DIRECTORY_VISUAL.groupMinHeight : MANGA_DIRECTORY_VISUAL.namedMinHeight })
            .padding<
    >({ left: this.facts(entry)?.group === true ? MANGA_DIRECTORY_VISUAL.groupPaddingX :
                this.query.trim().length > 0 || this.showContext || (this.liveEntry(entry)?.level ?? 1) <= 1 ? MANGA_DIRECTORY_VISUAL.namedPaddingX : MANGA_DIRECTORY_VISUAL.childPaddingLeft,
            right: this.facts(entry)?.group === true ? MANGA_DIRECTORY_VISUAL.groupPaddingX : MANGA_DIRECTORY_VISUAL.namedPaddingX,
            top: this.facts(entry)?.group === true ? MANGA_DIRECTORY_VISUAL.groupPaddingY : MANGA_DIRECTORY_VISUAL.namedPaddingY,
            bottom: this.facts(entry)?.group === true ? MANGA_DIRECTORY_VISUAL.groupPaddingY : MANGA_DIRECTORY_VISUAL.namedPaddingY })
            .margin<
    >({ top: this.row.groupSpacing ?? 0 })
            .border<
    >({ width: { bottom: this.facts(entry)?.group === true ||
                    this.branchControlsEnabled && this.facts(entry)?.readableParent === true ? 0 : MANGA_DIRECTORY_VISUAL.gridBorder }, color: this.color('line') })
            .backgroundColor<
    >(this.current(entry) ? this.color('active') : this.facts(entry)?.group === true ? this.color('soft') : Color.Transparent)
            .opacity<
    >(this.liveEntry(entry)?.navigable === false && this.facts(entry)?.group !== true ? MANGA_DIRECTORY_VISUAL.disabledOpacity : 1)
            .attributeModifier<
    >(new MangaDirectoryPressFeedback(this.interactionEnabled &&
            (this.facts(entry)?.group === true ? this.branchControlsEnabled && this.query.trim().length === 0 : this.liveEntry(entry) !== undefined && this.liveEntry(entry)?.navigable !== false), this.facts(entry)?.group !== true || this.interactionEnabled && this.branchControlsEnabled && this.query.trim().length === 0, this.scheme))
            .enabled<
    >(this.interactionEnabled && (this.facts(entry)?.group === true ? this.branchControlsEnabled && this.query.trim().length === 0 : this.liveEntry(entry) !== undefined && this.liveEntry(entry)?.navigable !== false))
            .accessibilityText<
    >(this.accessibility(entry)).onClick<
    >((): void => this.activateEntry(entry));
    }
    private emptySlots(): number[] {
        const slots: number[] = [];
        const count = Math.max(0, this.row.columns - this.row.entries.length);
        for (let index = 0; index < count; index += 1)
            slots.push(index);
        return slots;
    }
    build() {
        .width<
    >('100%').alignItems<
    >(HorizontalAlign.Start)
            .border<
    >({ width: { top: this.row.startIndex === 0 ? MANGA_DIRECTORY_VISUAL.gridBorder : 0 }, color: this.color('line') });
    }
}

import type { LocalReadingTocEntry } from '../reading/LocalReadingFlowGateway';
import type { ReaderDirectoryNavigationNode } from '../reading/ReaderDirectoryNavigation';
import type { MangaDirectoryRowPresentation } from './MangaDirectoryPresentation';
import { MANGA_DIRECTORY_VISUAL, mangaDirectoryLabelsFit, mangaDirectoryColumns } from './MangaDirectoryVisual.ts';
export interface MangaDirectoryLabel {
    kind: 'numeric' | 'parts' | 'named';
    numberText: string;
    part: '' | '上' | '中' | '下';
}
export interface MangaDirectoryLayoutRow {
    kind: 'row' | 'numeric' | 'parts';
    columns: number;
    startIndex: number;
    entries: LocalReadingTocEntry[];
    labels: MangaDirectoryLabel[];
    runStart?: boolean;
    runEnd?: boolean;
    groupSpacing?: number;
}
export interface MangaDirectoryNodeLayoutRow {
    kind: 'row' | 'numeric' | 'parts';
    columns: number;
    startIndex: number;
    nodes: ReaderDirectoryNavigationNode[];
    labels: MangaDirectoryLabel[];
}
export interface MangaDirectoryNodePlacement extends MangaDirectoryNodeLayoutRow {
    leader: boolean;
    rowLength: number;
}
export function mangaDirectoryLabel(title: string): MangaDirectoryLabel {
    const numeric = title.match(/^\s*(\d+)\s*$/);
    if (numeric !== null)
        return { kind: 'numeric', numberText: numeric[1], part: '' };
    const parts = title.match(/^\s*(\d+)\s*(?:[（(]\s*([上中下])\s*[）)]|([上中下]))\s*$/);
    if (parts !== null)
        return { kind: 'parts', numberText: parts[1], part: (parts[2] ?? parts[3]) as '上' | '中' | '下' };
    return { kind: 'named', numberText: '', part: '' };
}
export function mangaDirectoryGridColumns(kind: 'numeric' | 'parts' | 'named', hasMiddle: boolean, narrow: boolean = false, fontScale: number = 1, contentWidth: number = 0, labels: MangaDirectoryLabel[] = [], accessoryWidth: number = 0): number {
    return mangaDirectoryColumns(kind, hasMiddle, narrow, fontScale, contentWidth, labels.map((label: MangaDirectoryLabel): number => label.numberText.length), accessoryWidth);
}
function gridLabelsFit(labels: MangaDirectoryLabel[], fontScale: number, contentWidth: number, accessoryWidth: number): boolean {
    return labels.every((label: MangaDirectoryLabel): boolean => mangaDirectoryLabelsFit(label.kind, fontScale, contentWidth, [label.numberText.length], accessoryWidth));
}
export function mangaDirectorySameNodeRun(left: ReaderDirectoryNavigationNode, right: ReaderDirectoryNavigationNode): boolean {
    const label = mangaDirectoryLabel(left.title);
    return left.kind === 'target' && right.kind === 'target' && !left.hasChildren && !right.hasChildren &&
        label.kind !== 'named' && label.kind === mangaDirectoryLabel(right.title).kind &&
        left.parentId === right.parentId && left.depth === right.depth;
}
function gridNode(node: ReaderDirectoryNavigationNode): boolean {
    return node.kind === 'target' && !node.hasChildren && mangaDirectoryLabel(node.title).kind !== 'named';
}
export function mangaDirectoryNodeRows(nodes: ReaderDirectoryNavigationNode[], narrow: boolean = false, offset: number = 0, fontScale: number = 1, contentWidth: number = 0, accessoryWidth: number = 0): MangaDirectoryNodeLayoutRow[] {
    const rows: MangaDirectoryNodeLayoutRow[] = [];
    let start = 0;
    while (start < nodes.length) {
        const first = nodes[start];
        if (!gridNode(first)) {
            rows.push({ kind: 'row', columns: 1, startIndex: offset + start, nodes: [first], labels: [mangaDirectoryLabel(first.title)] });
            start += 1;
            continue;
        }
        let end = start + 1;
        while (end < nodes.length && mangaDirectorySameNodeRun(first, nodes[end]))
            end += 1;
        const labels = nodes.slice(start, end).map((node: ReaderDirectoryNavigationNode): MangaDirectoryLabel => mangaDirectoryLabel(node.title));
        const kind = labels[0].kind as 'numeric' | 'parts';
        if (!gridLabelsFit(labels, fontScale, contentWidth, accessoryWidth)) {
            for (let at = start; at < end; at += 1)
                rows.push({ kind: 'row', columns: 1, startIndex: offset + at,
                    nodes: [nodes[at]], labels: [labels[at - start]] });
            start = end;
            continue;
        }
        const columns = mangaDirectoryGridColumns(kind, labels.some((label: MangaDirectoryLabel): boolean => label.part === '中'), narrow, fontScale, contentWidth, labels, accessoryWidth);
        for (let at = start; at < end; at += columns) {
            rows.push({ kind, columns, startIndex: offset + at, nodes: nodes.slice(at, Math.min(end, at + columns)),
                labels: labels.slice(at - start, Math.min(end - start, at - start + columns)) });
        }
        start = end;
    }
    return rows;
}
export function mangaDirectoryNodePlacement(nodes: ReaderDirectoryNavigationNode[], ordinal: number, narrow: boolean = false, offset: number = 0, fontScale: number = 1, contentWidth: number = 0, accessoryWidth: number = 0): MangaDirectoryNodePlacement | undefined {
    if (!Number.isInteger(ordinal) || ordinal < 0 || ordinal >= nodes.length)
        return undefined;
    const target = nodes[ordinal];
    if (!gridNode(target))
        return { kind: 'row', columns: 1, startIndex: offset + ordinal,
            nodes: [target], labels: [mangaDirectoryLabel(target.title)], leader: true, rowLength: 1 };
    let start = ordinal;
    let end = ordinal + 1;
    while (start > 0 && mangaDirectorySameNodeRun(target, nodes[start - 1]))
        start -= 1;
    while (end < nodes.length && mangaDirectorySameNodeRun(target, nodes[end]))
        end += 1;
    const kind = mangaDirectoryLabel(target.title).kind as 'numeric' | 'parts';
    const labels = nodes.slice(start, end).map((node: ReaderDirectoryNavigationNode): MangaDirectoryLabel => mangaDirectoryLabel(node.title));
    if (!gridLabelsFit(labels, fontScale, contentWidth, accessoryWidth))
        return { kind: 'row', columns: 1, startIndex: offset + ordinal,
            nodes: [target], labels: [mangaDirectoryLabel(target.title)], leader: true, rowLength: 1 };
    const columns = mangaDirectoryGridColumns(kind, labels.some((label: MangaDirectoryLabel): boolean => label.part === '中'), narrow, fontScale, contentWidth, labels, accessoryWidth);
    const rowStart = start + Math.floor((ordinal - start) / columns) * columns;
    const rowNodes = nodes.slice(rowStart, Math.min(end, rowStart + columns));
    return { kind, columns, startIndex: offset + rowStart, nodes: rowNodes,
        labels: rowNodes.map((node: ReaderDirectoryNavigationNode): MangaDirectoryLabel => mangaDirectoryLabel(node.title)),
        leader: ordinal === rowStart, rowLength: rowNodes.length };
}
export function mangaDirectoryNodePlacements(nodes: ReaderDirectoryNavigationNode[], narrow: boolean = false, offset: number = 0, fontScale: number = 1, contentWidth: number = 0, accessoryWidth: number = 0): MangaDirectoryNodePlacement[] {
    const result: MangaDirectoryNodePlacement[] = [];
    for (const row of mangaDirectoryNodeRows(nodes, narrow, offset, fontScale, contentWidth, accessoryWidth)) {
        for (let ordinal = 0; ordinal < row.nodes.length; ordinal += 1) {
            result.push({ kind: row.kind, columns: row.columns, startIndex: row.startIndex,
                nodes: row.nodes, labels: row.labels, leader: ordinal === 0, rowLength: row.nodes.length });
        }
    }
    return result;
}
function gridEntry(entry: LocalReadingTocEntry, presentation: Map<number, MangaDirectoryRowPresentation>): boolean {
    return entry.navigable === true && presentation.get(entry.index)?.hasChildren !== true &&
        mangaDirectoryLabel(entry.title).kind !== 'named';
}
function sameEntryRun(left: LocalReadingTocEntry, right: LocalReadingTocEntry, presentation: Map<number, MangaDirectoryRowPresentation>): boolean {
    return gridEntry(left, presentation) && gridEntry(right, presentation) && left.level === right.level &&
        presentation.get(left.index)?.parentIndex === presentation.get(right.index)?.parentIndex &&
        mangaDirectoryLabel(left.title).kind === mangaDirectoryLabel(right.title).kind;
