import type { LocalReadingTocEntry } from '../reading/LocalReadingFlowGateway';
export interface MangaDirectoryRowPresentation {
    parentTitle?: string;
    parentIndex?: number;
    contextTitle?: string;
    readableDescendantCount?: number;
    ancestorGroupIndexes: number[];
    group: boolean;
    hasChildren: boolean;
    readableParent: boolean;
    countComplete: boolean;
}
export function mangaDirectoryHasChildren(entries: LocalReadingTocEntry[], ordinal: number): boolean {
    const entry = entries[ordinal];
    const level = entry?.level;
    const nextLevel = entries[ordinal + 1]?.level;
    return level !== undefined && Number.isInteger(level) && level >= 1 &&
        nextLevel !== undefined && Number.isInteger(nextLevel) && nextLevel > level;
}
export function mangaDirectoryIsGroup(entries: LocalReadingTocEntry[], ordinal: number): boolean {
    return entries[ordinal]?.navigable === false && mangaDirectoryHasChildren(entries, ordinal);
}
export function mangaDirectoryPresentation(entries: LocalReadingTocEntry[]): Map<number, MangaDirectoryRowPresentation> {
    const presentation: Map<number, MangaDirectoryRowPresentation> = new Map<number, MangaDirectoryRowPresentation>();
    const ancestors: LocalReadingTocEntry[] = [];
    for (let ordinal = 0; ordinal < entries.length; ordinal += 1) {
        const entry = entries[ordinal];
        const level = entry.level;
        if (level === undefined || !Number.isInteger(level) || level < 1) {
            for (const ancestor of ancestors) {
                const value = presentation.get(ancestor.index);
                if (value !== undefined)
                    value.countComplete = false;
            }
            ancestors.length = 0;
            continue;
        }
        while (ancestors.length > 0 && (ancestors[ancestors.length - 1].level ?? 1) >= level)
            ancestors.pop();
        const parent = ancestors.length === 0 ? undefined : ancestors[ancestors.length - 1];
        const hasChildren = mangaDirectoryHasChildren(entries, ordinal);
        const group = entry.navigable === false && hasChildren;
        presentation.set(entry.index, { group, countComplete: true,
            hasChildren, readableParent: entry.navigable === true && hasChildren,
            ancestorGroupIndexes: ancestors.map((ancestor: LocalReadingTocEntry): number => ancestor.index),
            parentIndex: parent?.index, parentTitle: parent?.title,
            contextTitle: ancestors.length === 0 ? undefined : ancestors.map((ancestor: LocalReadingTocEntry): string => ancestor.title).join(' / '),
            readableDescendantCount: hasChildren ? 0 : undefined });
        for (const ancestor of ancestors) {
            const value = presentation.get(ancestor.index);
            if (value === undefined)
                continue;
            if (entry.navigable === true)
                value.readableDescendantCount = (value.readableDescendantCount ?? 0) + 1;
            else if (entry.navigable === undefined)
                value.countComplete = false;
        }
        if (hasChildren)
            ancestors.push(entry);
    }
    return presentation;
}
export function mangaDirectoryVisibleEntries(entries: LocalReadingTocEntry[], presentation: Map<number, MangaDirectoryRowPresentation>, collapsedGroups: number[]): LocalReadingTocEntry[] {
    const collapsed: Set<number> = new Set<number>(collapsedGroups);
    return entries.filter((entry: LocalReadingTocEntry): boolean => !(presentation.get(entry.index)?.ancestorGroupIndexes ?? []).some((index: number): boolean => collapsed.has(index)));
}

