    const inner = Math.max(1, contentWidth - (MANGA_DIRECTORY_VISUAL.footerPaddingX + MANGA_DIRECTORY_VISUAL.borderWidth) * 2);
    const pageEm = Array.from(position).reduce((sum: number, character: string): number => sum + (character.charCodeAt(0) < 128 ? MANGA_DIRECTORY_VISUAL.numericDigitWidthEm : 1), 0);
    const pageLines = position.length === 0 ? 0 : Math.max(1, Math.ceil(pageEm * MANGA_DIRECTORY_VISUAL.footerMetaFontSize * scale / inner));
    return Math.max(MANGA_DIRECTORY_VISUAL.footerHeight, (MANGA_DIRECTORY_VISUAL.footerMetaLineHeight * (1 + pageLines) + MANGA_DIRECTORY_VISUAL.footerTitleLineHeight) * scale + MANGA_DIRECTORY_VISUAL.footerStackGap * (pageLines > 0 ? 2 : 1) + (MANGA_DIRECTORY_VISUAL.footerPaddingY + MANGA_DIRECTORY_VISUAL.borderWidth) * 2);
