export function mangaDirectoryColor(role: string, scheme: string): string {
    const dark = scheme === 'night' || scheme === 'theme-dark';
    switch (role) {
        case 'paper': return dark ? '#1C1E1A' : '#F8F4EC';
        case 'surface': return dark ? '#282C25' : '#FFFCF8';
        case 'soft': return dark ? '#30342D' : '#F0ECE3';
        case 'ink': return dark ? '#EAE7DE' : '#1F1B17';
        case 'muted': return dark ? '#ABA99F' : '#756F69';
        case 'faint': return dark ? '#767D71' : '#A39C90';
        case 'green': return dark ? '#324C37' : '#1F3528';
        case 'accent': return dark ? '#B9CEB1' : '#425D45';
        case 'onGreen': return dark ? '#FFFAF4' : '#FFFAF4';
        case 'active': return dark ? '#303C2D' : '#E8EDE2';
        case 'line': return dark ? '#3B4036' : '#E7E0D5';
        case 'frame': return dark ? '#4D5447' : '#D7D0C3';
        case 'shadow': return dark ? '#29000000' : '#12372A18';
        case 'handle': return dark ? '#565E50' : '#C9C9C4';
        case 'scrim': return dark ? '#57000000' : '#57000000';
        case 'scrollbar': return dark ? '#47000000' : '#47000000';
        default: return dark ? '#EAE7DE' : '#1F1B17';
    }
}
export function mangaDirectoryScale(fontScale: number): number {
    return Number.isFinite(fontScale) && fontScale > 0 ? fontScale : 1;
}
export function mangaDirectoryLineBox(minimum: number, line: number, verticalPadding: number, fontScale: number): number {
    return Math.max(minimum, line * mangaDirectoryScale(fontScale) + verticalPadding);
}
export function mangaDirectoryQuickMinimumListHeight(fontScale: number): number {
    return Math.min(MANGA_DIRECTORY_VISUAL.quickMaxListHeight, Math.max(MANGA_DIRECTORY_VISUAL.gridHeight, MANGA_DIRECTORY_VISUAL.namedMinHeight) * mangaDirectoryScale(fontScale));
}
export function mangaDirectoryFullFlowFooter(viewportHeight: number, fontScale: number, safeTop: number, safeBottom: number, footerHeight: number): boolean {
    if (!Number.isFinite(viewportHeight) || viewportHeight <= 0)
        return false;
    const scale = mangaDirectoryScale(fontScale);
    const headerBottom = Math.max(0, safeTop) + MANGA_DIRECTORY_VISUAL.headerSafeGap + mangaDirectoryHeaderHeight(scale);
    const footerTop = viewportHeight - Math.max(0, safeBottom) - MANGA_DIRECTORY_VISUAL.footerBottom - Math.max(0, footerHeight);
    const minimum = Math.max(MANGA_DIRECTORY_VISUAL.namedMinHeight, MANGA_DIRECTORY_VISUAL.namedLineHeight * scale + MANGA_DIRECTORY_VISUAL.namedPaddingY * 2 + MANGA_DIRECTORY_VISUAL.gridBorder);
    return footerTop - headerBottom < minimum;
}
export function mangaDirectoryQuickFlowGaps(): number {
    return MANGA_DIRECTORY_VISUAL.quickGap * 2;
}
export function mangaDirectoryPositionStacked(contentWidth: number, fontScale: number, position: string): boolean {
    if (!Number.isFinite(contentWidth) || contentWidth <= 0)
