    @State
    private footerHeight: number = 0;
    @State
    private viewportWidth: number = 0;
    scroller: Scroller = new Scroller();
    @BuilderParam
    content: () => void = this.emptySlot;
    @BuilderParam
    header: () => void = this.emptySlot;
    @BuilderParam
    footer: () => void = this.emptySlot;
    @BuilderParam
    overlayContent: () => void = this.emptySlot;
