import { TYPE_FORM_COMPACT_ACTION } from './ReaderTypography';
import { readerAppColor } from './ReaderThemeRegistry';
@Component
export struct ReaderRecoveryAction extends   {
    constructor(?: {
        private appThemeScheme?: string;
        variant?: 'compact' | 'rssManagement';
        label?: string;
        generation?: number;
        actionEnabled?: boolean;
        onReconcile?: (generation: number) => void;
    }, ?: ) { }
    @StorageLink('readerAppScheme')
    private appThemeScheme: string = 'day';
    @Prop
    variant: 'compact' | 'rssManagement' = 'compact';
    @Prop
    label: string = '刷新列表';
    @Prop
    generation: number = 0;
    @Prop
    actionEnabled: boolean = true;
    onReconcile: (generation: number) => void = (_generation: number): void => { };
    build() {
            .fontFamily<
    >(TYPE_FORM_COMPACT_ACTION.fontFamily)
            .fontWeight<
    >(TYPE_FORM_COMPACT_ACTION.fontWeight)
            .fontSize<
    >(TYPE_FORM_COMPACT_ACTION.fontSizeFp)
            .fontColor<
    >(readerAppColor('TOK_PRIMARY_TEXT', this.appThemeScheme))
            .height<
    >(36)
            .padding<
    >({ left: 12, right: 12 })
            .backgroundColor<
    >(readerAppColor('TOK_PRIMARY_SOFT', this.appThemeScheme))
            .borderRadius<
    >(this.variant === 'rssManagement' ? 8 : 6)
            .textAlign<
    >(TextAlign.Center)
            .enabled<
    >(this.actionEnabled)
            .focusable<
    >(this.actionEnabled)
            .accessibilityRole<
    >(AccessibilityRoleType.BUTTON)
            .accessibilityText<
    >(this.label)
            .onClick<
    >((): void => { if (this.actionEnabled)
            this.onReconcile(this.generation); });
    }
}

